/* Game Boy / Game Boy Color support (API version 4). Uses the ROMs generated by make_gb_rom.py (see its docstring for
 * the WRAM contract): boot, frames, framebuffer content (DMG green palette, CGB colours, no SGB border), audio rate and
 * a tone, keys, battery save and MBC3 RTC footer round trips, save states, reset, virtual RTC, platform switching and
 * the refusal of the GBA-only link/group APIs.   test_gb <gb-rom-dir> <gba-rom> */
#include "gbacore.h"
#include "gbacore_priv.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int g_fail = 0;
#define CHECK(cond, ...) do { if (!(cond)) { ++g_fail; printf("  FAIL %s:%d: ", __FILE__, __LINE__); printf(__VA_ARGS__); printf("\n"); } } while (0)

#define KA 1
#define KB 2
#define KSEL 4
#define KSTART 8
#define KRIGHT 16
#define KLEFT 32
#define KUP 64
#define KDOWN 128

static gba_core* load(const char* dir, const char* name) {
	char path[1024];
	snprintf(path, sizeof(path), "%s/%s", dir, name);
	gba_core* c = gba_create();
	if (!c || gba_load_rom(c, path) != 0) {
		printf("  cannot load %s\n", path);
		exit(2);
	}
	return c;
}

static long long g_audio;
static int run(gba_core* c, int frames, uint32_t keys) {
	int16_t pcm[4096];
	gba_set_keys(c, keys);
	for (int i = 0; i < frames; ++i) {
		if (gba_run_frame(c) != GBA_RUN_FRAME_DONE) { CHECK(0, "run_frame failed"); return -1; }
		size_t n;
		while ((n = gba_read_audio(c, pcm, 2048)) > 0) g_audio += (long long) n;
	}
	return 0;
}

static int wram(gba_core* c, uint32_t addr) { return gba_priv_read16(c, addr) & 0xFF; }
static int counter(gba_core* c) { return wram(c, 0xC010) * 100 + wram(c, 0xC011) * 10 + wram(c, 0xC012); }

static uint32_t px(gba_core* c, int x, int y) {
	const uint8_t* p = gba_framebuffer(c) + ((size_t) y * gba_frame_width(c) + x) * 4;
	return (uint32_t) p[0] << 16 | (uint32_t) p[1] << 8 | p[2] | (uint32_t) p[3] << 24;
}

/* 5 bit quantisation mGBA applies to palette colours */
static uint32_t q5(uint32_t rgb) {
	uint32_t out = 0;
	for (int s = 16; s >= 0; s -= 8) {
		uint32_t v = (rgb >> s) & 0xFF;
		v >>= 3;
		v = (v << 3) | (v >> 2);
		out |= v << s;
	}
	return out;
}

static uint32_t fbhash(gba_core* c) {
	uint32_t h = 2166136261u;
	size_t n = (size_t) gba_frame_width(c) * gba_frame_height(c) * 4;
	const uint8_t* p = gba_framebuffer(c);
	for (size_t i = 0; i < n; ++i) h = (h ^ p[i]) * 16777619u;
	return h;
}

static uint32_t statehash(gba_core* c) {
	size_t n = gba_state_size(c);
	uint8_t* b = malloc(n);
	if (gba_save_state(c, b, n) != n) { CHECK(0, "save_state"); free(b); return 0; }
	uint32_t h = 2166136261u;
	for (size_t i = 0; i < n; ++i) h = (h ^ b[i]) * 16777619u;
	free(b);
	return h;
}

static uint32_t keymap_hw(uint32_t m) { return ((m >> 4) & 0xF) | ((m & 0xF) << 4); }

static void test_common(const char* dir, const char* name, int cgb, size_t saveSize, const char* title, const char* code) {
	printf("== %s\n", name);
	gba_core* c = load(dir, name);
	CHECK(gba_platform(c) == GBA_PLATFORM_GB, "platform");
	CHECK(gba_frame_width(c) == 160 && gba_frame_height(c) == 144, "frame size %dx%d", gba_frame_width(c), gba_frame_height(c));
	char t[16], k[8];
	CHECK(gba_rom_info(c, t, k) == 0, "rom_info");
	CHECK(strcmp(t, title) == 0 && strcmp(k, code) == 0, "rom info '%s' '%s' (want '%s' '%s')", t, k, title, code);
	CHECK(gba_save_size(c) == saveSize, "save size %zu (want %zu)", gba_save_size(c), saveSize);

	/* boot, framebuffer, audio */
	g_audio = 0;
	run(c, 120, 0);
	long long a120 = g_audio;
	CHECK(a120 > 120 * 546 && a120 < 120 * 556, "audio frames %lld for 120 video frames", a120);
	CHECK(wram(c, 0xC003) >= 100 && wram(c, 0xC003) <= 120, "program runs once per frame: %d", wram(c, 0xC003));
	uint32_t seen[64];
	int distinct = 0, opaque = 1;
	for (int y = 0; y < 144; ++y)
		for (int x = 0; x < 160; ++x) {
			uint32_t v = px(c, x, y);
			if ((v >> 24) != 0xFF) opaque = 0;
			int f = 0;
			for (int i = 0; i < distinct; ++i) if (seen[i] == v) { f = 1; break; }
			if (!f && distinct < 64) seen[distinct++] = v;
		}
	CHECK(opaque, "alpha is 255 everywhere");
	if (!cgb) {
		static const uint32_t pal[4] = { 0xE0F8D0, 0x88C070, 0x346856, 0x081820 };
		CHECK(distinct == 4, "DMG picture uses exactly the 4 palette shades, got %d", distinct);
		for (int i = 0; i < distinct; ++i) {
			int ok = 0;
			for (int j = 0; j < 4; ++j) ok |= ((seen[i] & 0xFFFFFF) == q5(pal[j]));
			CHECK(ok, "colour %06x is not a green palette shade", seen[i] & 0xFFFFFF);
		}
		CHECK((px(c, 0, 0) & 0xFFFFFF) == q5(0x081820), "border colour %06x", px(c, 0, 0) & 0xFFFFFF);
		CHECK((px(c, 80, 100) & 0xFFFFFF) == q5(0xE0F8D0), "background colour %06x", px(c, 80, 100) & 0xFFFFFF);
	} else {
		CHECK(distinct >= 12, "CGB picture is colourful: %d colours", distinct);
		CHECK((px(c, 0, 0) & 0xFFFFFF) != q5(0x081820) && (px(c, 0, 0) & 0xFF0000) > 0x300000, "CGB border colour %06x", px(c, 0, 0) & 0xFFFFFF);
	}
	/* a tone: channel 1 produces non-silent audio (recorded after the first 120 frames) */
	{
		int16_t pcm[4096];
		long peak = 0;
		for (int i = 0; i < 10; ++i) {
			gba_run_frame(c);
			size_t n = gba_read_audio(c, pcm, 2048);
			for (size_t j = 0; j < n * 2; ++j) peak = peak < labs(pcm[j]) ? labs(pcm[j]) : peak;
		}
		CHECK(peak > 200, "audio peak %ld (tone expected)", peak);
	}

	/* keys: GBA-style mask -> hardware joypad, L/R ignored */
	run(c, 4, KA | KUP | KSTART);
	CHECK(wram(c, 0xC001) == (int) keymap_hw(KA | KUP | KSTART), "joypad now %02x (want %02x)", wram(c, 0xC001), keymap_hw(KA | KUP | KSTART));
	run(c, 4, KRIGHT | KDOWN | KB | KSEL);
	CHECK(wram(c, 0xC001) == (int) keymap_hw(KRIGHT | KDOWN | KB | KSEL), "joypad others %02x", wram(c, 0xC001));
	run(c, 4, KLEFT);
	CHECK(wram(c, 0xC001) == (int) keymap_hw(KLEFT), "joypad left %02x", wram(c, 0xC001));
	run(c, 4, 0x300);
	CHECK(wram(c, 0xC001) == 0, "L/R must be ignored, joypad %02x", wram(c, 0xC001));
	gba_set_keys(c, 0xFFFFFFFFu);
	run(c, 4, 0);
	gba_destroy(c);
}

static void test_save_state(const char* dir, const char* name, size_t saveSize) {
	printf("== saves and states: %s\n", name);
	gba_core* c = load(dir, name);
	run(c, 30, 0);
	CHECK(counter(c) == 0, "fresh counter %d", counter(c));
	for (int i = 0; i < 5; ++i) { run(c, 3, KA); run(c, 3, 0); }
	CHECK(counter(c) == 5, "counter after 5 presses: %d", counter(c));
	CHECK(gba_save_dirty(c) == 1, "save dirty after the game wrote RAM");
	size_t n = gba_save_size(c);
	uint8_t* sav = calloc(n + 1, 1);
	size_t got = gba_get_save(c, sav, n);
	CHECK(got == saveSize, "get_save wrote %zu (want %zu)", got, saveSize);
	CHECK(gba_save_dirty(c) == 0, "not dirty right after get_save");
	CHECK(memcmp(sav, "GBS1", 4) == 0 && sav[4] == 0 && sav[5] == 0 && sav[6] == 5, "save content %02x %02x %02x", sav[4], sav[5], sav[6]);
	if (saveSize > 8192) {
		/* VBA-compatible footer: 5 + 5 u32 registers and the u64 UNIX time of the last latch */
		uint64_t ut = 0;
		for (int i = 0; i < 8; ++i) ut |= (uint64_t) sav[8192 + 40 + i] << (8 * i);
		CHECK(ut > 1700000000ull, "footer unix time %llu", (unsigned long long) ut);
	}
	/* a new core with that save shows the same counter */
	gba_core* d = load(dir, name);
	CHECK(gba_load_save(d, sav, got) == 0, "load_save");
	CHECK(gba_save_dirty(d) == 0, "loaded save is not dirty");
	run(d, 20, 0);
	CHECK(counter(d) == 5, "counter restored from the save: %d", counter(d));
	/* ... and keeps counting from there */
	run(d, 3, KA); run(d, 3, 0);
	CHECK(counter(d) == 6, "counter continues: %d", counter(d));
	CHECK(gba_save_dirty(d) == 1, "dirty again");
	/* a save that is too short / empty still boots (fresh game) */
	gba_core* e = load(dir, name);
	CHECK(gba_load_save(e, sav, 0) == 0, "empty save");
	run(e, 20, 0);
	CHECK(counter(e) == 0, "fresh counter after an empty save: %d", counter(e));
	gba_destroy(e);

	/* states: save at frame N, continue; a fresh core loading the state replays identically */
	run(c, 7, KUP);
	size_t sn = gba_state_size(c);
	CHECK(sn > 1000, "state size %zu", sn);
	uint8_t* st = calloc(sn, 1);
	CHECK(gba_save_state(c, st, sn) == sn, "save_state");
	uint32_t s0 = statehash(c);
	run(c, 40, KA);
	run(c, 40, 0);
	uint32_t h1 = fbhash(c), sh1 = statehash(c);
	int cnt1 = counter(c);
	CHECK(gba_load_state(d, st, sn) == 0, "load_state into another core");
	CHECK(statehash(d) == s0, "loaded state hashes like the saved one");
	run(d, 40, KA);
	run(d, 40, 0);
	CHECK(fbhash(d) == h1 && statehash(d) == sh1 && counter(d) == cnt1, "replay from the state is identical");
	CHECK(gba_load_state(c, st, sn) == 0, "load_state into the same core");
	run(c, 40, KA);
	run(c, 40, 0);
	CHECK(fbhash(c) == h1 && statehash(c) == sh1, "same-core replay identical");
	CHECK(gba_load_state(c, st, sn - 1) < 0, "short state rejected");
	CHECK(gba_load_state(c, st, sn + 128) < 0, "state with a group trailer rejected for Game Boy");
	/* reset restarts the program but the battery RAM stays */
	gba_reset(c);
	run(c, 12, 0);
	CHECK(wram(c, 0xC003) <= 12, "frame counter restarted after reset: %d", wram(c, 0xC003));
	CHECK(counter(c) == cnt1, "counter survives a reset (cartridge RAM): %d vs %d", counter(c), cnt1);
	free(st);
	free(sav);
	gba_destroy(d);
	gba_destroy(c);
}

static void put32(uint8_t* p, uint32_t v) { p[0] = v; p[1] = v >> 8; p[2] = v >> 16; p[3] = v >> 24; }

static void test_rtc(const char* dir) {
	printf("== MBC3 RTC (virtual clock)\n");
	const int64_t E = 1760000000;
	gba_core* c = load(dir, "gb_dmg.gb");
	CHECK(gba_set_rtc(c, E, GBA_RTC_VIRTUAL) == 0, "set_rtc");
	CHECK(gba_priv_rtc_unix(c) == E, "virtual start %lld", (long long) gba_priv_rtc_unix(c));
	run(c, 600, 0); /* 10.05 s of emulated time */
	CHECK(gba_priv_rtc_unix(c) == E + 10, "virtual clock advances with frames (%lld)", (long long) (gba_priv_rtc_unix(c) - E));
	run(c, 2, KSTART);
	run(c, 3, 0);
	CHECK(wram(c, 0xC023) == 1, "START latched the clock");
	CHECK(wram(c, 0xC020) == 10 && wram(c, 0xC021) == 0 && wram(c, 0xC022) == 0, "fresh cart clock reads 0:00:10, got %d:%02d:%02d",
	      wram(c, 0xC022), wram(c, 0xC021), wram(c, 0xC020));
	gba_destroy(c);

	/* a save made earlier carries the clock: 5:30:00 on day 1, last latched 100 s before "now" */
	uint8_t sav[8192 + 48];
	memset(sav, 0xFF, 8192);
	memcpy(sav, "GBS1", 4);
	memset(sav + 8192, 0, 48);
	put32(sav + 8192 + 0, 0);  /* sec */
	put32(sav + 8192 + 4, 30); /* min */
	put32(sav + 8192 + 8, 5);  /* hour */
	put32(sav + 8192 + 12, 1); /* days */
	/* mGBA restores the clock registers from the latched copy: store the same values there */
	for (int i = 0; i < 5; ++i) memcpy(sav + 8192 + 20 + 4 * i, sav + 8192 + 4 * i, 4);
	uint64_t ut = (uint64_t) (E - 100);
	for (int i = 0; i < 8; ++i) sav[8192 + 40 + i] = (uint8_t) (ut >> (8 * i));
	c = load(dir, "gb_dmg.gb");
	gba_set_rtc(c, E, GBA_RTC_VIRTUAL);
	CHECK(gba_load_save(c, sav, sizeof(sav)) == 0, "load save with footer");
	run(c, 120, 0);
	run(c, 2, KSTART);
	run(c, 3, 0);
	CHECK(wram(c, 0xC022) == 5 && wram(c, 0xC021) == 31 && wram(c, 0xC020) >= 41 && wram(c, 0xC020) <= 43,
	      "clock from the save advanced by 100 s + 2 s: %d:%02d:%02d", wram(c, 0xC022), wram(c, 0xC021), wram(c, 0xC020));
	/* the footer written back is current */
	uint8_t out[8192 + 48];
	CHECK(gba_get_save(c, out, sizeof(out)) == sizeof(out), "get_save with footer");
	uint64_t ut2 = 0;
	for (int i = 0; i < 8; ++i) ut2 |= (uint64_t) out[8192 + 40 + i] << (8 * i);
	CHECK(ut2 >= (uint64_t) E + 2 && ut2 <= (uint64_t) E + 4, "footer time %lld after E", (long long) (ut2 - E));
	/* wall mode: the clock follows the machine again and the in-game time stays continuous */
	CHECK(gba_set_rtc(c, 0, GBA_RTC_WALL) == 0, "back to the wall clock");
	gba_destroy(c);
}

static void test_sgb(const char* dir) {
	printf("== SGB-flagged ROM runs as plain 160x144 DMG\n");
	gba_core* c = load(dir, "gb_sgb.gb");
	run(c, 60, 0);
	CHECK(gba_frame_width(c) == 160 && gba_frame_height(c) == 144, "no Super Game Boy border");
	CHECK((px(c, 0, 0) & 0xFFFFFF) == q5(0x081820), "green DMG colours, got %06x", px(c, 0, 0) & 0xFFFFFF);
	gba_destroy(c);
}

static void test_link_refusal(const char* dir) {
	printf("== GBA-only APIs refuse Game Boy cores\n");
	gba_core* c = load(dir, "gb_dmg.gb");
	gba_link_configure(c, 0, 2);
	gba_link_configure(c, 1, 4);
	uint8_t m[64] = { 1, 0, 1, 2, 0, 0, 0, 0, 0 };
	gba_link_deliver(c, 1, m, 9);
	run(c, 10, 0);
	CHECK(gba_link_poll_outgoing(c, m, sizeof(m)) == 0, "no outgoing link message from a Game Boy core");
	gba_group* g = gba_group_create(2);
	CHECK(g != NULL, "group create");
	CHECK(gba_group_add(g, c) < 0, "group_add refuses a Game Boy core");
	gba_group_destroy(g);
	run(c, 10, 0);
	gba_destroy(c);
}

static void test_switch(const char* dir, const char* gba) {
	printf("== switching platforms in one core\n");
	char path[1024];
	snprintf(path, sizeof(path), "%s/gb_cgb.gbc", dir);
	gba_core* c = gba_create();
	CHECK(gba_platform(c) == GBA_PLATFORM_GBA && gba_frame_width(c) == 240, "fresh core is GBA");
	CHECK(gba_load_rom(c, path) == 0 && gba_platform(c) == GBA_PLATFORM_GB, "GBC loaded into a fresh core");
	run(c, 20, 0);
	CHECK(gba_load_rom(c, gba) == 0 && gba_platform(c) == GBA_PLATFORM_GBA && gba_frame_width(c) == 240 && gba_frame_height(c) == 160, "GBA ROM replaces it");
	run(c, 20, KA);
	gba_link_configure(c, 0, 2); /* the GBA link works again after the switch */
	run(c, 5, 0);
	CHECK(gba_load_rom(c, path) == 0 && gba_platform(c) == GBA_PLATFORM_GB, "and back");
	snprintf(path, sizeof(path), "%s/gb_dmg.gb", dir);
	CHECK(gba_load_rom(c, path) == 0, "DMG after CGB reloads a fresh model");
	run(c, 60, 0);
	CHECK((px(c, 0, 0) & 0xFFFFFF) == q5(0x081820), "DMG colours after a CGB game, got %06x", px(c, 0, 0) & 0xFFFFFF);
	CHECK(gba_load_rom(c, "/nonexistent/x.gb") < 0, "missing file fails");
	gba_destroy(c);
}

int main(int argc, char** argv) {
	if (argc < 3) return 2;
	const char* dir = argv[1];
	printf("api version %u\n", gba_api_version());
	CHECK(gba_api_version() == 4, "api version");
	test_common(dir, "gb_dmg.gb", 0, 8192 + 48, "GBTESTDMG", "G332");
	test_common(dir, "gb_cgb.gbc", 1, 8192, "GBTESTCGB", "GBCT");
	test_save_state(dir, "gb_dmg.gb", 8192 + 48);
	test_save_state(dir, "gb_cgb.gbc", 8192);
	test_rtc(dir);
	test_sgb(dir);
	test_link_refusal(dir);
	test_switch(dir, argv[2]);
	printf(g_fail ? "FAILED (%d)\n" : "ok\n", g_fail);
	return g_fail ? 1 : 0;
}
